#!/usr/bin/env python3
"""Minimal LLM eval runner. Generated by `eos scaffold llm-evals`; yours to edit.

Reads evals/llm/cases.jsonl, renders each case's prompt file with its vars, calls the model with the settings
pinned in the prompt's frontmatter, grades the output with code (contains / regex / JSON keys / length), and
writes per-case results that `eos llm gate` compares with evals/llm/gate.json and the committed baseline.

  python evals/llm/run_evals.py                 # real calls (OPENAI_API_KEY from the environment / CI secret)
  python evals/llm/run_evals.py --fake          # no calls: grades each case's fake_output (tests the pipeline)
  python .eos/bin/eos.py llm gate evals/llm/results.json

Outputs are not written to results unless --keep-outputs (they may contain personal data). Add model-graded
criteria (a judge prompt + rubric, calibrated against human labels) only where code cannot grade.
Why and how: .eos/packs/ref/llm/evals-in-production.md
"""

from __future__ import annotations

import argparse
import datetime as dt
import json
import os
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
VAR_RX = re.compile(r"\{\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}\}")


def load_prompt(prompt_id: str) -> tuple[dict, str]:
    """Find <id>.prompt.md (or prompts/<id>.md) and split frontmatter (key: value, [a, b] lists) from the body."""
    for p in [*ROOT.rglob(f"{prompt_id}.prompt.md"), ROOT / "prompts" / f"{prompt_id}.md"]:
        if p.is_file() and "node_modules" not in p.parts:
            text = p.read_text(encoding="utf-8")
            head, _, body = text[4:].partition("\n---\n")
            meta: dict = {}
            for line in head.splitlines():
                key, sep, val = line.partition(":")
                if sep and not line.lstrip().startswith("#"):
                    val = re.sub(r"\s+#.*$", "", val).strip()
                    meta[key.strip()] = [x.strip() for x in val[1:-1].split(",")] if val.startswith("[") else val
            return meta, body.strip()
    raise SystemExit(f"prompt {prompt_id!r} not found (expected {prompt_id}.prompt.md or prompts/{prompt_id}.md)")


def render(body: str, variables: dict) -> str:
    missing = sorted(set(VAR_RX.findall(body)) - set(variables))
    if missing:
        raise SystemExit(f"missing vars: {', '.join(missing)}")
    return VAR_RX.sub(lambda m: str(variables[m.group(1)]), body)


def call_model(meta: dict, prompt: str) -> str:
    """One model call with explicit limits. Swap this function for your provider or your app's own LLM module."""
    from openai import OpenAI  # uv run --with openai==<pinned> (see the workflow)

    client = OpenAI(timeout=60.0, max_retries=2)
    kwargs = {"model": meta["model"], "input": prompt, "max_output_tokens": int(meta["max_output_tokens"])}
    if "temperature" in meta:
        kwargs["temperature"] = float(meta["temperature"])
    return client.responses.create(**kwargs).output_text


def grade(output: str, expect: dict) -> list[str]:
    """Code graders. Returns the list of failed checks (empty = pass)."""
    low, fails = output.lower(), []
    for s in expect.get("contains", []):
        if s.lower() not in low:
            fails.append(f"missing {s!r}")
    if expect.get("contains_any") and not any(s.lower() in low for s in expect["contains_any"]):
        fails.append(f"none of {expect['contains_any']!r}")
    for s in expect.get("not_contains", []):
        if s.lower() in low:
            fails.append(f"contains forbidden {s!r}")
    if expect.get("regex") and not re.search(expect["regex"], output):
        fails.append(f"no match for /{expect['regex']}/")
    if expect.get("max_chars") and len(output) > int(expect["max_chars"]):
        fails.append(f"{len(output)} chars > {expect['max_chars']}")
    if expect.get("json_keys"):
        try:
            data = json.loads(output)
            fails += [f"JSON key {k!r} missing" for k in expect["json_keys"] if k not in data]
        except ValueError:
            fails.append("output is not JSON")
    return fails


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--cases", default=str(ROOT / "evals/llm/cases.jsonl"))
    ap.add_argument("--out", default=str(ROOT / "evals/llm/results.json"))
    ap.add_argument("--fake", action="store_true", help="grade fake_output instead of calling the model")
    ap.add_argument("--repeats", type=int, default=1, help="runs per case; a case passes only if every run passes")
    ap.add_argument("--max-calls", type=int, default=int(os.environ.get("EVAL_MAX_CALLS", "200")))
    ap.add_argument("--only-tag", help="run only cases with this tag (e.g. a fast PR subset)")
    ap.add_argument("--keep-outputs", action="store_true", help="store outputs in results (may hold personal data)")
    a = ap.parse_args()
    cases = [json.loads(ln) for ln in Path(a.cases).read_text(encoding="utf-8").splitlines() if ln.strip()]
    if a.only_tag:
        cases = [c for c in cases if a.only_tag in c.get("tags", [])]
    if len(cases) * a.repeats > a.max_calls and not a.fake:
        print(f"{len(cases) * a.repeats} calls > --max-calls {a.max_calls}; raise it deliberately", file=sys.stderr)
        return 2
    out, versions = [], {}
    for c in cases:
        meta, body = load_prompt(c["prompt"])
        versions[meta.get("id", c["prompt"])] = meta.get("version")
        prompt = render(body, c.get("vars", {}))
        fails, outputs = [], []
        for _ in range(a.repeats):
            text = c.get("fake_output", "") if a.fake else call_model(meta, prompt)
            outputs.append(text)
            fails += grade(text, c.get("expect", {}))
        row = {"id": c["id"], "pass": not fails, "tags": c.get("tags", []), "failures": sorted(set(fails))}
        if a.keep_outputs:
            row["outputs"] = outputs
        out.append(row)
        print(f"{'pass' if not fails else 'FAIL'}  {c['id']}  {'; '.join(sorted(set(fails)))}")
    result = {
        "created": dt.datetime.now(dt.timezone.utc).isoformat(timespec="seconds"),
        "fake": a.fake,
        "prompt_versions": versions,
        "cases": out,
    }
    Path(a.out).parent.mkdir(parents=True, exist_ok=True)
    Path(a.out).write_text(json.dumps(result, indent=1, ensure_ascii=False) + "\n", encoding="utf-8")
    print(f"wrote {a.out}: {sum(r['pass'] for r in out)}/{len(out)} passed")
    return 0


if __name__ == "__main__":
    sys.exit(main())
